const brawlers=[
 {name:'Ranger',emoji:'🧢',color:'#75d8ef',rarity:'RARE',hp:5400,damage:920,speed:3,style:'balanced'},
 {name:'Ember',emoji:'🔥',color:'#ffad75',rarity:'RARE',hp:5000,damage:850,speed:4,style:'fast'},
 {name:'Boulder',emoji:'🪨',color:'#c6a988',rarity:'SUPER RARE',hp:7900,damage:1100,speed:2,style:'tank'},
 {name:'Pip',emoji:'🐥',color:'#ffe875',rarity:'RARE',hp:4300,damage:700,speed:5,style:'fast'},
 {name:'Valkyrie',emoji:'⚔️',color:'#e4a4ff',rarity:'EPIC',hp:6100,damage:1050,speed:3,style:'balanced'},
 {name:'Ninja',emoji:'🥷',color:'#8d9cf0',rarity:'EPIC',hp:4800,damage:980,speed:5,style:'fast'},
 {name:'Sunny',emoji:'🌞',color:'#ffd36c',rarity:'RARE',hp:5500,damage:800,speed:3,style:'balanced'},
 {name:'Frost',emoji:'❄️',color:'#9ce8ff',rarity:'SUPER RARE',hp:5200,damage:900,speed:3,style:'balanced'},
 {name:'Mochi',emoji:'🐼',color:'#eee',rarity:'EPIC',hp:6700,damage:880,speed:2,style:'tank'},
 {name:'Roxy',emoji:'🦊',color:'#ffbd7d',rarity:'RARE',hp:5100,damage:840,speed:4,style:'fast'},
 {name:'Captain',emoji:'🏴‍☠️',color:'#f4cc68',rarity:'MYTHIC',hp:6000,damage:1020,speed:3,style:'balanced'},
 {name:'Zappy',emoji:'⚡',color:'#f5ef8c',rarity:'SUPER RARE',hp:4700,damage:760,speed:5,style:'fast'},
 {name:'Cactus',emoji:'🌵',color:'#a9e289',rarity:'RARE',hp:5800,damage:940,speed:3,style:'balanced'},
 {name:'Phantom',emoji:'👻',color:'#c8c6ff',rarity:'MYTHIC',hp:5000,damage:1200,speed:4,style:'fast'},
 {name:'Bubbles',emoji:'🐸',color:'#a4edb8',rarity:'SUPER RARE',hp:6300,damage:870,speed:3,style:'balanced'},
 {name:'Dynamo',emoji:'🤖',color:'#9ad3ff',rarity:'EPIC',hp:7200,damage:980,speed:2,style:'tank'},
 {name:'Luna',emoji:'🌙',color:'#c2aaff',rarity:'MYTHIC',hp:4800,damage:1000,speed:4,style:'fast'},
 {name:'Poppy',emoji:'🌺',color:'#ff9ab3',rarity:'RARE',hp:5300,damage:820,speed:4,style:'balanced'},
 {name:'Rex',emoji:'🦖',color:'#87d78b',rarity:'LEGENDARY',hp:7600,damage:1150,speed:3,style:'tank'},
 {name:'Pixel',emoji:'👾',color:'#b8a5ff',rarity:'LEGENDARY',hp:5600,damage:1080,speed:4,style:'fast'}
];
const canvas=document.getElementById('game'),ctx=canvas.getContext('2d'),wrap=document.getElementById('arenaWrap');let selected=0,mode='menu',last=0,elapsed=0,player=null,enemies=[],bullets=[],cubes=[],particles=[],keys={},moveTouch={x:0,y:0},attackHeld=false,superHeld=false,attackCD=0,superCharge=0,toastTimer=0,camShake=0,matchReward=0;
const W=1040,H=670,arena={w:1700,h:1200};let treeSpots=[],wallSpots=[];
function seeded(seed){let x=seed;return()=>{x=(x*1664525+1013904223)>>>0;return x/4294967296}}
function makeMap(){let r=seeded(319);treeSpots=[];wallSpots=[];for(let i=0;i<64;i++){let x=55+r()*(arena.w-110),y=55+r()*(arena.h-110);treeSpots.push({x,y,r:15+r()*8,c:['#387a55','#438d5c','#519968'][i%3],s:r()})}for(let i=0;i<27;i++){let x=100+r()*(arena.w-200),y=90+r()*(arena.h-180),w=38+r()*45,h=30+r()*45;if(Math.hypot(x-arena.w/2,y-arena.h/2)<165)continue;wallSpots.push({x,y,w,h})}}
makeMap();
function fit(){let dpr=Math.min(devicePixelRatio||1,2),rect=wrap.getBoundingClientRect();canvas.width=Math.floor(rect.width*dpr);canvas.height=Math.floor(rect.height*dpr);ctx.setTransform(dpr,0,0,dpr,0,0)}new ResizeObserver(fit).observe(wrap);fit();
const roster=document.getElementById('roster');brawlers.forEach((b,i)=>{let item=document.createElement('button');item.className='roster-item';item.setAttribute('aria-label',b.name);item.title=b.name;item.style.setProperty('--tile',b.color);item.innerHTML=b.emoji+(i<6?`<small>${i+1}</small>`:'');item.onclick=()=>choose(i);roster.append(item)});
function choose(i){selected=i;const b=brawlers[i];document.querySelectorAll('.roster-item').forEach((el,j)=>el.classList.toggle('active',i===j));document.getElementById('portrait').textContent=b.emoji;document.getElementById('portrait').style.background=b.color;document.getElementById('profileName').textContent=b.name;document.getElementById('rarity').textContent='★ '+b.rarity;document.getElementById('hpStat').textContent=b.hp;document.getElementById('damageStat').textContent=b.damage;document.getElementById('speedStat').textContent='★'.repeat(b.speed);document.getElementById('hudAvatar').textContent=b.emoji;document.getElementById('hudAvatar').style.background=b.color;document.getElementById('hudName').textContent=b.name;if(mode==='playing'){player.maxHp=b.hp;player.hp=Math.min(player.hp,b.hp);player.damage=b.damage;player.speed=104+b.speed*10;player.emoji=b.emoji;player.color=b.color}toast(`${b.emoji} ${b.name} selected!`)}choose(0);
function toast(msg){const t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),1350)}
function startGame(){const b=brawlers[selected];player={x:arena.w/2,y:arena.h/2,r:19,hp:b.hp,maxHp:b.hp,damage:b.damage,speed:104+b.speed*10,emoji:b.emoji,color:b.color,angle:0,cubes:0,invuln:0};enemies=[];bullets=[];particles=[];cubes=[];superCharge=0;elapsed=0;attackCD=0;camShake=0;let rng=seeded(Date.now()%999999+selected*99);for(let i=0;i<9;i++){let a=Math.PI*2*i/9+rng()*.3,d=410+rng()*310;let eb=brawlers[(i*2+Math.floor(rng()*19)+1)%20];enemies.push({x:clamp(arena.w/2+Math.cos(a)*d,45,arena.w-45),y:clamp(arena.h/2+Math.sin(a)*d,45,arena.h-45),r:17,hp:eb.hp*.72,maxHp:eb.hp*.72,damage:eb.damage*.65,speed:56+rng()*23,emoji:eb.emoji,color:eb.color,angle:a+Math.PI,cd:.5+rng()*2,turn:rng()*3.5,stun:0})}for(let i=0;i<13;i++){let a=rng()*Math.PI*2,d=80+rng()*640;cubes.push({x:clamp(arena.w/2+Math.cos(a)*d,60,arena.w-60),y:clamp(arena.h/2+Math.sin(a)*d,60,arena.h-60),r:9,spin:rng()*6})}mode='playing';document.getElementById('overlay').classList.add('hidden');document.getElementById('countdown').classList.remove('hidden');let n=3;document.getElementById('countdown').textContent=n;const tick=()=>{if(mode!=='playing')return;if(n>1){n--;document.getElementById('countdown').textContent=n;setTimeout(tick,500)}else{document.getElementById('countdown').classList.add('hidden');document.getElementById('countdown').textContent=''} };setTimeout(tick,500);last=performance.now();requestAnimationFrame(loop)}
document.getElementById('startBtn').onclick=startGame;document.getElementById('selectBtn').onclick=()=>{roster.scrollIntoView({behavior:'smooth',block:'center'});toast('Choose any of 20 brawlers!')};
function clamp(v,a,b){return Math.max(a,Math.min(b,v))}function norm(x,y){let m=Math.hypot(x,y)||1;return{x:x/m,y:y/m}}
function blocked(x,y,r){for(const w of wallSpots)if(x+r>w.x&&x-r<w.x+w.w&&y+r>w.y&&y-r<w.y+w.h)return w;return null}
function move(o,dx,dy){let nx=clamp(o.x+dx,o.r+18,arena.w-o.r-18),ny=clamp(o.y+dy,o.r+18,arena.h-o.r-18);if(!blocked(nx,o.y,o.r))o.x=nx;if(!blocked(o.x,ny,o.r))o.y=ny}
function fire(owner,target,superShot=false){if(!target)return;let a=Math.atan2(target.y-owner.y,target.x-owner.x);if(owner===player)owner.angle=a;let speed=superShot?470:390,count=owner===player&&!superShot?3:1,spread=count===3?.18:0;for(let i=0;i<count;i++){let ang=a+(i-(count-1)/2)*spread;bullets.push({x:owner.x+Math.cos(ang)*(owner.r+6),y:owner.y+Math.sin(ang)*(owner.r+6),vx:Math.cos(ang)*speed,vy:Math.sin(ang)*speed,r:superShot?8:6,damage:(owner.damage||player.damage)*(superShot?1.65:count===3?.43:1),life:superShot?1.05:1.28,owner:owner===player?'player':'enemy',color:owner===player?'#fff5b9':'#ff7680',super:superShot})}}
function attack(){if(mode!=='playing'||attackCD>0)return;let closest=null,dist=600;for(const e of enemies){let d=Math.hypot(e.x-player.x,e.y-player.y);if(d<dist){dist=d;closest=e}}if(closest){fire(player,closest);attackCD=.43;particles.push({x:player.x+Math.cos(player.angle)*27,y:player.y+Math.sin(player.angle)*27,life:.15,max:.15,color:'#fff5a8',r:15})}else{player.angle=Math.atan2((keys.ArrowDown||keys.s?1:0)-(keys.ArrowUp||keys.w?1:0), (keys.ArrowRight||keys.d?1:0)-(keys.ArrowLeft||keys.a?1:0))||player.angle;fire(player,{x:player.x+Math.cos(player.angle)*150,y:player.y+Math.sin(player.angle)*150});attackCD=.43}}
function useSuper(){if(mode!=='playing'||superCharge<100)return;superCharge=0;let closest=null,dist=750;for(const e of enemies){let d=Math.hypot(e.x-player.x,e.y-player.y);if(d<dist){dist=d;closest=e}}if(closest)fire(player,closest,true);else{for(let i=0;i<8;i++){let a=i*Math.PI/4;bullets.push({x:player.x,y:player.y,vx:Math.cos(a)*430,vy:Math.sin(a)*430,r:8,damage:player.damage*1.35,life:.9,owner:'player',color:'#9affd1',super:true})}}toast('SUPER ATTACK! ⚡')}
function update(dt){if(mode!=='playing')return;elapsed+=dt;attackCD=Math.max(0,attackCD-dt);if(player.invuln>0)player.invuln-=dt;let mx=(keys.ArrowRight||keys.d?1:0)-(keys.ArrowLeft||keys.a?1:0)+moveTouch.x,my=(keys.ArrowDown||keys.s?1:0)-(keys.ArrowUp||keys.w?1:0)+moveTouch.y;if(mx||my){let v=norm(mx,my);move(player,v.x*player.speed*dt,v.y*player.speed*dt);player.angle=Math.atan2(v.y,v.x)}if(attackHeld||keys[' '])attack();if(superHeld||keys.e)useSuper();for(let i=enemies.length-1;i>=0;i--){let e=enemies[i];e.cd-=dt;if(e.stun>0){e.stun-=dt;continue}let d=Math.hypot(player.x-e.x,player.y-e.y),angle=Math.atan2(player.y-e.y,player.x-e.x);if(d<315){e.angle=angle;if(d>150)move(e,Math.cos(angle)*e.speed*dt,Math.sin(angle)*e.speed*dt);else if(d<95)move(e,-Math.cos(angle)*e.speed*.55*dt,-Math.sin(angle)*e.speed*.55*dt);if(e.cd<=0&&d<325){fire(e,player);e.cd=1.35+Math.random()*.55}}else{e.turn-=dt;if(e.turn<0){e.turn=1+Math.random()*2;e.angle+=Math.random()*2-1}move(e,Math.cos(e.angle)*e.speed*.55*dt,Math.sin(e.angle)*e.speed*.55*dt)}if(Math.hypot(e.x-player.x,e.y-player.y)<e.r+player.r+1){player.hp-=175*dt;camShake=2}for(const c of cubes){if(c.r>0&&Math.hypot(e.x-c.x,e.y-c.y)<e.r+13){e.hp+=220;e.maxHp+=220;c.r=0}}if(e.hp<=0){dropCube(e.x,e.y);enemies.splice(i,1);makeBurst(e.x,e.y,e.color);continue}}
 for(let i=bullets.length-1;i>=0;i--){let b=bullets[i];b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt;let gone=b.life<=0||b.x<10||b.y<10||b.x>arena.w-10||b.y>arena.h-10||blocked(b.x,b.y,b.r);if(!gone&&b.owner==='player'){for(const e of enemies){if(Math.hypot(e.x-b.x,e.y-b.y)<e.r+b.r){e.hp-=b.damage;e.stun=.06;superCharge=Math.min(100,superCharge+(b.super?13:7));if(e.hp<=0){dropCube(e.x,e.y);makeBurst(e.x,e.y,e.color)}gone=true;break}}}else if(!gone&&b.owner==='enemy'&&Math.hypot(player.x-b.x,player.y-b.y)<player.r+b.r){player.hp-=b.damage;player.invuln=.08;camShake=3;gone=true}if(gone)bullets.splice(i,1)}
 for(const c of cubes){if(!c.r)continue;c.spin+=dt*3;if(Math.hypot(c.x-player.x,c.y-player.y)<player.r+17){c.r=0;player.cubes++;player.maxHp+=220;player.hp=Math.min(player.maxHp,player.hp+450);player.damage+=player.damage*.045;superCharge=Math.min(100,superCharge+6);toast('POWER CUBE! +health +damage');makeBurst(c.x,c.y,'#6dffb0')}}for(let i=particles.length-1;i>=0;i--){particles[i].life-=dt;if(particles[i].life<=0)particles.splice(i,1)}camShake=Math.max(0,camShake-dt*14);if(player.hp<=0){player.hp=0;finish(false);return}if(!enemies.length){finish(true);return}if(elapsed>=150){finish(false);return}document.getElementById('timer').textContent=`${Math.floor((150-elapsed)/60)}:${String(Math.floor(150-elapsed)%60).padStart(2,'0')}`;document.getElementById('alive').textContent=enemies.length+1;document.getElementById('health').style.width=`${100*player.hp/player.maxHp}%`;document.getElementById('health').style.background=player.hp/player.maxHp<.3?'#ff5362':'#56e88a';document.getElementById('superBtn').style.filter=superCharge>=100?'drop-shadow(0 0 7px #65ff8c)':''}
function dropCube(x,y){cubes.push({x,y,r:9,spin:0})}function makeBurst(x,y,color){for(let i=0;i<8;i++){let a=Math.PI*2*i/8;particles.push({x,y,vx:Math.cos(a)*70,vy:Math.sin(a)*70,life:.4,max:.4,color,r:4})}}
function finish(win){mode=win?'won':'lost';document.getElementById('countdown').classList.add('hidden');document.getElementById('overlay').classList.remove('hidden');let coins=win?45:Math.max(8,Math.floor(player.cubes*4));matchReward=coins;let body=document.querySelector('.dialog');body.innerHTML=`<div class="dialog-emoji">${win?'🏆':'💥'}</div><h1>${win?'VICTORY!':'BUSTED!'}</h1><p>${win?'You are the last brawler standing! What a showdown!':`You took out ${9-enemies.length} brawler${9-enemies.length===1?'':'s'} and collected ${player.cubes} power cube${player.cubes===1?'':'s'}. Ready for a rematch?`}</p><div style="font:900 14px 'DM Sans';color:#b7791f">🪙 +${coins} COINS &nbsp; · &nbsp; ☠ ${9-enemies.length} TAKEDOWNS</div><button class="again-btn" id="againBtn">↻ &nbsp; PLAY AGAIN</button><div class="subnote">Choose a different brawler to try a new style!</div>`;document.getElementById('againBtn').onclick=()=>{document.getElementById('coins').textContent=Number(document.getElementById('coins').textContent)+coins;startGame()}}

function draw(){let rect=wrap.getBoundingClientRect(),vw=rect.width,vh=rect.height;if(!vw||!vh)return;let scale=Math.min(vw/W,vh/H);let viewW=vw/scale,viewH=vh/scale;let cx=player?player.x:arena.w/2,cy=player?player.y:arena.h/2;let camX=clamp(cx-viewW/2,0,arena.w-viewW),camY=clamp(cy-viewH/2,0,arena.h-viewH);ctx.setTransform(1,0,0,1,0,0);ctx.clearRect(0,0,canvas.width,canvas.height);let dpr=canvas.width/vw;ctx.setTransform(scale*dpr,0,0,scale*dpr,-camX*scale*dpr,-camY*scale*dpr);ctx.save();if(camShake){ctx.translate((Math.random()-.5)*camShake,(Math.random()-.5)*camShake)}
 // bright, illustrated arena
 ctx.fillStyle='#a5d777';ctx.fillRect(0,0,arena.w,arena.h);ctx.fillStyle='#aee07e';for(let x=28;x<arena.w;x+=68)for(let y=25;y<arena.h;y+=68){ctx.beginPath();ctx.arc(x+((y/68|0)%2)*20,y,1.7,0,Math.PI*2);ctx.fill()}ctx.strokeStyle='#77b75e';ctx.lineWidth=7;ctx.strokeRect(17,17,arena.w-34,arena.h-34);ctx.strokeStyle='#c9ed98';ctx.lineWidth=2;ctx.strokeRect(25,25,arena.w-50,arena.h-50);
 // central oasis
 ctx.fillStyle='#b9e58b';ctx.beginPath();ctx.ellipse(arena.w/2,arena.h/2,188,140,-.2,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#8cce6a';ctx.lineWidth=4;ctx.stroke();ctx.fillStyle='#8bcb6d';ctx.beginPath();ctx.arc(arena.w/2,arena.h/2,47,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#d5f1a4';ctx.lineWidth=4;ctx.stroke();for(let i=0;i<6;i++){let a=i*Math.PI/3;ctx.fillStyle='#72b95e';ctx.beginPath();ctx.ellipse(arena.w/2+Math.cos(a)*68,arena.h/2+Math.sin(a)*58,13,6,a,0,Math.PI*2);ctx.fill()}
 // cover, shadows, decorations
 for(const w of wallSpots){ctx.fillStyle='#5e9561';roundRect(w.x+4,w.y+7,w.w,w.h,8);ctx.fillStyle='#c89258';roundRect(w.x,w.y,w.w,w.h,8);ctx.fillStyle='#dfb873';roundRect(w.x+3,w.y+3,w.w-6,9,4);ctx.strokeStyle='#a87546';ctx.lineWidth=2;ctx.strokeRect(w.x+3,w.y+3,w.w-6,w.h-6);ctx.beginPath();ctx.moveTo(w.x+8,w.y+17);ctx.lineTo(w.x+w.w-8,w.y+17);ctx.stroke()}
 for(const t of treeSpots){ctx.fillStyle='#527b50';ctx.beginPath();ctx.ellipse(t.x+2,t.y+9,t.r*1.1,t.r*.68,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=t.c;ctx.beginPath();ctx.arc(t.x,t.y,t.r,0,Math.PI*2);ctx.fill();ctx.fillStyle='#75b56b';ctx.beginPath();ctx.arc(t.x-t.r*.25,t.y-t.r*.28,t.r*.45,0,Math.PI*2);ctx.fill();ctx.fillStyle='#d2eca0';ctx.beginPath();ctx.arc(t.x-t.r*.28,t.y-t.r*.25,2.4,0,Math.PI*2);ctx.fill()}
 // battle pickups
 for(const c of cubes){if(!c.r)continue;ctx.save();ctx.translate(c.x,c.y);ctx.rotate(c.spin);ctx.shadowColor='#3c9766';ctx.shadowBlur=6;ctx.fillStyle='#69efa0';roundRect(-8,-8,16,16,4);ctx.shadowBlur=0;ctx.strokeStyle='#f0ffe6';ctx.lineWidth=2;ctx.strokeRect(-5,-5,10,10);ctx.restore()}
 // projectiles
 for(const b of bullets){ctx.fillStyle=b.color;ctx.shadowColor=b.color;ctx.shadowBlur=b.super?13:7;ctx.beginPath();ctx.arc(b.x,b.y,b.r,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(b.x-2,b.y-2,b.r*.38,0,Math.PI*2);ctx.fill()}
 for(const p of particles){let q=p.life/p.max;ctx.globalAlpha=q;ctx.fillStyle=p.color;if(p.vx){ctx.beginPath();ctx.arc(p.x,p.y,p.r*q,0,Math.PI*2);ctx.fill()}else{ctx.beginPath();ctx.arc(p.x,p.y,p.r*(1-q*.5),0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1}
 for(const e of enemies)drawBrawler(e,false);if(player)drawBrawler(player,true);
 // world border / storm hint
 ctx.strokeStyle='#467f51';ctx.lineWidth=16;ctx.strokeRect(3,3,arena.w-6,arena.h-6);ctx.restore();
 // draw super meter at top edge on desktop/mobile
 if(player){ctx.setTransform(dpr,0,0,dpr,0,0);let width=Math.min(118,vw*.28),x=vw-width-12,y=vh-28;ctx.fillStyle='#14253dce';roundRect(x,y,width,15,7);ctx.fillStyle=superCharge>=100?'#6dff9d':'#74e6a3';roundRect(x+2,y+2,(width-4)*superCharge/100,11,5);ctx.fillStyle='#fff';ctx.font='800 8px DM Sans';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(superCharge>=100?'SUPER READY  ⚡':'SUPER',x+width/2,y+7.5)} }
function roundRect(x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill()}
function drawBrawler(o,isPlayer){ctx.save();ctx.translate(o.x,o.y);ctx.fillStyle='#416d4a';ctx.beginPath();ctx.ellipse(1,13,o.r*.94,o.r*.56,0,0,Math.PI*2);ctx.fill();ctx.rotate(o.angle||0);ctx.fillStyle=isPlayer?'#243953':'#74454b';roundRect(7,-6,19,12,5);ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(0,0,o.r,0,Math.PI*2);ctx.fill();ctx.lineWidth=isPlayer?3:2;ctx.strokeStyle=isPlayer?'#fff5b4':'#fff';ctx.stroke();ctx.beginPath();ctx.arc(0,0,o.r-3,0,Math.PI*2);ctx.fillStyle=o.color;ctx.fill();ctx.rotate(-(o.angle||0));ctx.font=`${o.r*1.48}px serif`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(o.emoji,0,1);ctx.restore();if(!isPlayer){let pct=Math.max(0,o.hp/o.maxHp);ctx.fillStyle='#47343a';roundRect(o.x-17,o.y-o.r-12,34,5,3);ctx.fillStyle='#55e779';roundRect(o.x-16,o.y-o.r-11,32*pct,3,2)}if(isPlayer&&o.invuln>0){ctx.strokeStyle='#fff';ctx.lineWidth=3;ctx.beginPath();ctx.arc(o.x,o.y,o.r+6,0,Math.PI*2);ctx.stroke()}}
function loop(t){if(mode!=='playing')return;let dt=Math.min(.035,(t-last)/1000||0);last=t;update(dt);draw();if(mode==='playing')requestAnimationFrame(loop)}
window.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();keys[e.key]=true;if(e.key===' '){attackHeld=true;attack()}if(e.key.toLowerCase()==='e')useSuper();if(e.key>='1'&&e.key<='6')choose(Number(e.key)-1)});window.addEventListener('keyup',e=>{keys[e.key]=false;if(e.key===' ')attackHeld=false});
