g:15px}.dialog{width:min(440px,95%);background:#fff9eb;border:4px solid white;border-radius:22px;text-align:center;padding:25px;box-shadow:0 9px #b6a27d}.dialog h1{font:36px 'Lilita One';margin:5px;color:#193351}.dialog p{font-size:12px;line-height:1.5;color:#66758a}.sub{font-size:9px;color:#8993a2;font-weight:800;margin-top:10px}.hidden{display:none!important}.count{position:absolute;inset:0;display:grid;place-items:center;font:90px 'Lilita One';color:white;text-shadow:0 5px #254267;pointer-events:none;z-index:4}.toast{position:absolute;top:55px;left:50%;transform:translateX(-50%);background:#162943;color:white;padding:8px 14px;border-radius:20px;font-size:11px;font-weight:900;opacity:0;z-index:5;pointer-events:none}.toast.show{opacity:1}.mobile{display:none}.superMeter{position:absolute;bottom:9px;right:10px;background:#14253ddd;color:white;font-size:8px;font-weight:900;padding:5px 8px;border-radius:7px}
