(() => {
  'use strict';
  const $ = (id) => document.getElementById(id);
  const canvas = $('game'), ctx = canvas.getContext('2d'), arena = $('arena');
  const roster = [
    ['Ranger','🧢','RARE',5400,920,3,'#63b8e8','A steady all-rounder with a crisp three-shot burst.'],
    ['Ember','🔥','SUPER RARE',4700,1250,3,'#ff815e','A fiery close-range fighter who loves a crowd.'],
    ['Moss','🌱','RARE',6200,760,2,'#83c96d','A sturdy guardian with a healing pulse.'],
    ['Nova','🌟','EPIC',4300,1050,4,'#ed85e8','A star-slinger with quick feet and long reach.'],
    ['Boulder','🪨','RARE',7600,820,1,'#c29b70','Slow, tough, and very hard to move.'],
    ['Pip','🐸','SUPER RARE',3900,890,4,'#81d6a0','A nimble trickster who hops between shots.'],
    ['Volt','⚡','EPIC',4800,990,3,'#f3d54e','A charged-up duelist with a lightning super.'],
    ['Bubbles','🫧','RARE',5100,870,3,'#72d6ec','Bounces bubbly shots around the arena.'],
    ['Fang','🐯','MYTHIC',5600,1150,3,'#f4a54d','A fearless hunter built for the chase.'],
    ['Luna','🌙','EPIC',4400,960,4,'#a995ef','A moonlit sharpshooter with a graceful dash.'],
    ['Rivet','🤖','RARE',6800,720,2,'#91a7b5','A dependable bot with a powerful punch.'],
    ['Petal','🌸','SUPER RARE',5000,850,3,'#f286ae','A garden guardian who blooms under pressure.'],
    ['Blaze','🐲','MYTHIC',5200,1100,3,'#f07852','A little dragon with a huge flame burst.'],
    ['Echo','🎧','EPIC',4600,930,4,'#65c9c4','Keeps the beat while dodging every attack.'],
    ['Dune','🏜️','RARE',5900,810,2,'#e1bd67','A desert scout who never loses the trail.'],
    ['Wisp','👻','MYTHIC',4200,1050,4,'#bac9f5','A slippery spirit who strikes from afar.'],
    ['Clover','🍀','SUPER RARE',5500,800,3,'#82c772','A lucky brawler with a knack for survival.'],
    ['Comet','☄️','LEGENDARY',4900,1020,4,'#ff9271','A blazing comet that dashes through danger.'],
    ['Shell','🐢','RARE',7200,740,1,'#77c1a0','A patient tank who stands their ground.'],
    ['Jinx','🃏','MYTHIC',4500,980,3,'#bc82e7','A wildcard with a mischievous streak.']
  ].map(([name,emoji,rarity,hp,damage,speed,color,desc],i)=>({name,emoji,rarity,hp,damage,speed,color,desc,i}));
  let selected = Number(localStorage.getItem('starfall-brawler') || 0);
  if (!Number.isInteger(selected) || selected < 0 || selected >= roster.length) selected = 0;
  let W=0,H=0,dpr=1, raf=0, last=0, running=false, elapsed=0, toastTimer=0, coins=Number(localStorage.getItem('starfall-coins')||320);
  let player=null,bots=[],shots=[],cubes=[],particles=[],obstacles=[],keys={},moveTouch={x:0,y:0},attackHeld=false,superHeld=false,mouseAim=null,world={w:1500,h:1050},zone={x:750,y:525,r:760},shake=0;
  const clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),rand=(a,b)=>a+Math.random()*(b-a),dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
  const brawler=()=>roster[selected];
  function updateProfile(){const b=brawler(); $('portrait').textContent=b.emoji;$('name').textContent=b.name;$('rarity').textContent='★ '+b.rarity;$('hp').textContent=b.hp.toLocaleString();$('damage').textContent=b.damage.toLocaleString();$('speed').textContent='★'.repeat(b.speed);$('hudAvatar').textContent=b.emoji;$('hudName').textContent=b.name;renderGrid();}
  function renderGrid(){const grid=$('grid');grid.innerHTML='';roster.forEach((b,i)=>{const button=document.createElement('button');button.className='tile'+(i===selected?' active':'');button.style.setProperty('--tile',`linear-gradient(145deg,${b.color}55,#fff4d8)`);button.title=`${b.name} — ${b.rarity}`;button.setAttribute('aria-label',`Choose ${b.name}`);button.innerHTML=`${b.emoji}<small>${i+1}</small>`;button.addEventListener('click',()=>{selected=i;localStorage.setItem('starfall-brawler',i);updateProfile();if(running)showToast(`${b.name} selected for your next round`);});grid.appendChild(button);});}
  function resize(){const rect=arena.getBoundingClientRect();dpr=Math.min(devicePixelRatio||1,2);W=Math.max(1,rect.width);H=Math.max(1,rect.height);canvas.width=Math.round(W*dpr);canvas.height=Math.round(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);draw();}
  function showToast(message){const el=$('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),1500);}
  function startGame(){cancelAnimationFrame(raf);running=true;elapsed=0;last=performance.now();shots=[];cubes=[];particles=[];shake=0;zone={x:world.w/2,y:world.h/2,r:790};const b=brawler();player=makeFighter(b,world.w/2,world.h/2,true);bots=[];for(let i=0;i<9;i++){let a=rand(0,Math.PI*2),r=rand(300,650);bots.push(makeFighter(roster[(selected+i+1+Math.floor(Math.random()*19))%20],clamp(world.w/2+Math.cos(a)*r,55,world.w-55),clamp(world.h/2+Math.sin(a)*r,55,world.h-55),false));}for(let i=0;i<33;i++)cubes.push({x:rand(80,world.w-80),y:rand(80,world.h-80),r:10,bob:rand(0,6),alive:true});obstacles=[];for(let i=0;i<43;i++){const x=rand(70,world.w-70),y=rand(70,world.h-70);if(Math.hypot(x-world.w/2,y-world.h/2)>115)obstacles.push({x,y,r:rand(23,39),bush:Math.random()<.58,variant:Math.random()});}
    $('overlay').classList.add('hidden');$('count').classList.remove('hidden');let n=3;$('count').textContent=n;const count=setInterval(()=>{n--;if(n>0)$('count').textContent=n;else{$('count').classList.add('hidden');clearInterval(count);}},700);$('alive').textContent='10';$('health').style.width='100%';$('meter').textContent='SUPER 0%';raf=requestAnimationFrame(loop);}
  function makeFighter(b,x,y,isPlayer){return {b,x,y,r:isPlayer?19:18,hp:b.hp,maxHp:b.hp,ammo:3,reload:0,super:0,attackCd:rand(.1,.8),isPlayer,dead:false,angle:0,ai:rand(0,2),wander:rand(0,Math.PI*2),flash:0,cubes:0};}
  function loop(now){if(!running)return;const dt=Math.min(.04,(now-last)/1000||0);last=now;update(dt);draw();raf=requestAnimationFrame(loop);}
  function update(dt){elapsed+=dt;player.reload=Math.max(0,player.reload-dt);player.attackCd=Math.max(0,player.attackCd-dt);player.flash=Math.max(0,player.flash-dt);bots.forEach(b=>{b.reload=Math.max(0,b.reload-dt);b.attackCd=Math.max(0,b.attackCd-dt);b.flash=Math.max(0,b.flash-dt);});
    const speed=player.b.speed*54*(1+player.cubes*.035);let mx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0)+moveTouch.x,my=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0)+moveTouch.y;let ml=Math.hypot(mx,my);if(ml>1){mx/=ml;my/=ml;}move(player,mx*speed*dt,my*speed*dt);
    if(mouseAim){player.angle=Math.atan2(mouseAim.y-H/2,mouseAim.x-W/2);}else{let target=nearest(player,bots);if(target)player.angle=Math.atan2(target.y-player.y,target.x-player.x);}
    if(keys[' ']||attackHeld)fire(player);if(keys.e||superHeld)useSuper(player);
    bots.forEach(bot=>{if(bot.dead)return;bot.ai-=dt;const target=nearest(bot,[player,...bots]);if(!target)return;const d=dist(bot,target);if(bot.ai<=0){bot.ai=rand(.4,1.3);bot.wander=rand(0,Math.PI*2);}let dx=target.x-bot.x,dy=target.y-bot.y,ang=Math.atan2(dy,dx);bot.angle=ang;let forward=d>260?1:d<155?-.55:.14;let strafe=Math.sin(elapsed*1.7+bot.x)*.5;move(bot,(Math.cos(ang)*forward+Math.cos(ang+Math.PI/2)*strafe)*bot.b.speed*36*dt,(Math.sin(ang)*forward+Math.sin(ang+Math.PI/2)*strafe)*bot.b.speed*36*dt);if(d<490&&Math.random()<.9)fire(bot,target);if(bot.hp<bot.maxHp*.33&&bot.super>=100)useSuper(bot);});
    shots.forEach(s=>{s.x+=s.vx*dt;s.y+=s.vy*dt;s.life-=dt;if(s.x<5||s.y<5||s.x>world.w-5||s.y>world.h-5)s.life=0;for(const o of obstacles)if(s.life>0&&!o.bush&&Math.hypot(s.x-o.x,s.y-o.y)<o.r+s.r)s.life=0;const actors=[player,...bots];for(const t of actors){if(s.life>0&&!t.dead&&t!==s.owner&&Math.hypot(s.x-t.x,s.y-t.y)<t.r+s.r){hit(t,s);s.life=0;break;}}});shots=shots.filter(s=>s.life>0);
    for(const c of cubes){if(c.alive){c.bob+=dt*3;for(const f of [player,...bots])if(!f.dead&&Math.hypot(f.x-c.x,f.y-c.y)<f.r+14){c.alive=false;f.cubes++;f.hp=Math.min(f.maxHp*1.25,f.hp+f.maxHp*.13);if(f===player)showToast('Power cube collected! +13% health');break;}}}
    for(const f of [player,...bots])if(!f.dead){const edge=Math.hypot(f.x-zone.x,f.y-zone.y);if(edge>zone.r){f.hp-=dt*(220+(790-zone.r)*.55);if(f.hp<=0)kill(f,null);}}
    if(elapsed>34)zone.r=Math.max(120,790-(elapsed-34)*5.1);
    if(player.dead){finish(false);return;}const alive=bots.filter(b=>!b.dead);$('alive').textContent=String(alive.length+1);$('health').style.width=`${clamp(player.hp/player.maxHp*100,0,100)}%`;$('health').style.background=player.hp/player.maxHp<.28?'#ff5362':'#56e88a';$('meter').textContent=`SUPER ${Math.floor(player.super)}%`;const total=Math.max(0,150-Math.floor(elapsed));$('timer').textContent=`${Math.floor(total/60)}:${String(total%60).padStart(2,'0')}`;if(!alive.length){finish(true);return;}if(elapsed>=150){finish(true);return;}particles=particles.filter(p=>p.life>0);particles.forEach(p=>{p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=.97;p.vy*=.97;});shake=Math.max(0,shake-dt*20);
  }
  function move(f,dx,dy){f.x=clamp(f.x+dx,24,world.w-24);f.y=clamp(f.y+dy,24,world.h-24);for(const o of obstacles){const d=Math.hypot(f.x-o.x,f.y-o.y),min=f.r+o.r*.68;if(d<min&&!o.bush){const a=Math.atan2(f.y-o.y,f.x-o.x);f.x=o.x+Math.cos(a)*min;f.y=o.y+Math.sin(a)*min;}}}
  function nearest(f,list){let best=null,bd=Infinity;for(const t of list)if(t&&!t.dead&&t!==f){const d=(t.x-f.x)**2+(t.y-f.y)**2;if(d<bd){bd=d;best=t;}}return best;}
  function fire(f,target){if(f.dead||f.attackCd>0)return;if(f.ammo<=0){if(f.reload<=0){f.ammo=3;f.reload=1.5;}return;}if(!target)target=nearest(f,[player,...bots]);if(!target)return;f.ammo--;f.reload=f.ammo===0?1.4:.24;f.attackCd=.25;let angle=f.isPlayer&&mouseAim?f.angle:Math.atan2(target.y-f.y,target.x-f.x);if(!f.isPlayer)angle+=rand(-.16,.16);f.angle=angle;const spread=f.b.i%4===0?[-.1,0,.1]:[0];spread.forEach(off=>{const a=angle+off,v=390+(f.b.speed*9);shots.push({x:f.x+Math.cos(a)*(f.r+5),y:f.y+Math.sin(a)*(f.r+5),vx:Math.cos(a)*v,vy:Math.sin(a)*v,r:6,life:1.35,damage:f.b.damage*(1+f.cubes*.1),owner:f,color:f.b.color});});}
  function hit(target,s){target.hp-=s.damage;target.flash=.12;s.owner.super=Math.min(100,s.owner.super+14);if(s.owner===player)showToast('Direct hit!');for(let i=0;i<5;i++)particles.push({x:target.x,y:target.y,vx:rand(-90,90),vy:rand(-90,90),life:.28,color:s.color});if(target.hp<=0)kill(target,s.owner);}
  function kill(f,killer){if(f.dead)return;f.dead=true;for(let i=0;i<3;i++)cubes.push({x:f.x+rand(-18,18),y:f.y+rand(-18,18),r:10,bob:0,alive:true});if(killer===player){killer.super=Math.min(100,killer.super+22);coins+=8;localStorage.setItem('starfall-coins',coins);$('coins').textContent=coins;}for(let i=0;i<12;i++)particles.push({x:f.x,y:f.y,vx:rand(-150,150),vy:rand(-150,150),life:.55,color:f.b.color});if(f===player)showToast('You were knocked out!');}
  function useSuper(f){if(f.dead||f.super<100)return;f.super=0;const radius=f.isPlayer?210:145;for(const t of [player,...bots])if(!t.dead&&t!==f&&dist(f,t)<radius){t.hp-=f.b.damage*2.35;t.flash=.2;if(t.hp<=0)kill(t,f);}for(let i=0;i<26;i++){const a=i/26*Math.PI*2;particles.push({x:f.x,y:f.y,vx:Math.cos(a)*rand(80,270),vy:Math.sin(a)*rand(80,270),life:.55,color:f.b.color});}if(f===player)showToast('SUPER BLAST!');shake=10;}
  function finish(win){if(!running)return;running=false;cancelAnimationFrame(raf);if(win){coins+=40;localStorage.setItem('starfall-coins',coins);$('coins').textContent=coins;}$('overlay').classList.remove('hidden');$('dialog').innerHTML=`<div style="font-size:46px">${win?'🏆':'💫'}</div><h1>${win?'STARFALL CHAMPION!':'NICE TRY, BRAWLER!'}</h1><p>${win?'You outlasted the arena and earned 40 coins!':'You earned 8 coins for every rival you defeated. Jump back in and try a new brawler!'}</p><button class="play" id="start">↻ &nbsp; PLAY AGAIN</button><div class="sub">${win?'A true showdown legend!':'MOVE: WASD / ARROWS · ATTACK: SPACE · SUPER: E'}</div>`;$('start').addEventListener('click',startGame);}
  function draw(){if(!ctx||!W||!H)return;ctx.clearRect(0,0,W,H);const scale=Math.min(W/680,H/440);ctx.save();ctx.translate(W/2,H/2);ctx.scale(scale,scale);const viewW=W/scale,viewH=H/scale;const cx=player?player.x:world.w/2,cy=player?player.y:world.h/2;ctx.translate(-cx,-cy);ctx.fillStyle='#a5d777';ctx.fillRect(0,0,world.w,world.h);
    // arena grass texture and boundary
    for(let y=25;y<world.h;y+=64)for(let x=25;x<world.w;x+=64){ctx.fillStyle=((Math.floor(x/64)+Math.floor(y/64))%2)?'#9ed171':'#a9dc7c';ctx.fillRect(x,y,64,64);ctx.fillStyle='#8cc66b66';ctx.beginPath();ctx.arc(x+randSeed(x,y)*43,y+randSeed(y,x)*43,1.4,0,Math.PI*2);ctx.fill();}
    ctx.strokeStyle='#e7ffd1';ctx.lineWidth=12;ctx.strokeRect(0,0,world.w,world.h);ctx.strokeStyle='#507e4d';ctx.lineWidth=5;ctx.strokeRect(0,0,world.w,world.h);
    // zone warning
